ALTER TABLE "finance"."ledger_entries" ADD CONSTRAINT "ledger_entries_shop_by_kind" CHECK (("finance"."ledger_entries"."shop_id" is not null or "finance"."ledger_entries"."kind" in ('opex', 'supplier_payment', 'supplier_refund', 'cod_collected')) and ("finance"."ledger_entries"."shop_id" is null or "finance"."ledger_entries"."kind" not in ('supplier_payment', 'supplier_refund', 'opex')));